<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\DcrInitialAccessToken\Application\Usecase\Update;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Domain\DcrInitialAccessTokenRef;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Application\Service\Visibility\DcrInitialAccessTokenVisibilityService;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Domain\Gateway\DcrInitialAccessTokenCommandRepositoryGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class DcrInitialAccessTokenUpdateUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly DcrInitialAccessTokenVisibilityService $visibility,
        private readonly DcrInitialAccessTokenCommandRepositoryGateway $writer,
    ) {
    }

    public function allowUpdate(?DcrInitialAccessTokenRef $ref = null): Allow
    {
        $this->logDebug("Check allow update usecase for Dcr initial access token");
        $span = $this->startSpan("Check allow update usecase for Dcr initial access token");
        try {
            $result = $this->dispatcher->dispatch(new DcrInitialAccessTokenUpdateAllowDecision(Allow::allowed('update', 'Allowed to update by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function fixedFields(?DcrInitialAccessTokenRef $ref = null): array
    {
        $this->logDebug("Check fixed fields for update usecase for Dcr initial access token");
        $span = $this->startSpan("Check fixed fields for update usecase for Dcr initial access token");
        try {
            return $this->visibility->fieldsToFix($ref);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function update(string $uid, DcrInitialAccessTokenUpdateParams $params): DcrInitialAccessTokenUpdateResult
    {
        $this->logDebug("Run update usecase for Dcr initial access token");
        $span = $this->startSpan("Run update usecase for Dcr initial access token");
        try {
            $ref = new DcrInitialAccessTokenRef($uid);
            $allow = $this->allowUpdate($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to update Dcr initial access token');
            }
            if (!$original = $this->visibility->retrieveVisibleForUpdate($ref)) {
                throw new NotFoundException($uid);
            }
            $this->dispatcher->dispatch(new DcrInitialAccessTokenUpdateCheck($params, $original));
            $enriched = $this->dispatcher->dispatch(new DcrInitialAccessTokenUpdateEnrich($params, $original, $params->toAttributes()));
            $attributes = $enriched->getResult();
            $input = $this->visibility->copyWithFixed($attributes);
            $modified = $original->update($input);
            $result = $this->writer->update($original, $modified);
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new DcrInitialAccessTokenUpdateResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
